local KTool = CS.Engine.Lib.KTool
local Singleton = import('Frame.Singleton')

---@class ActivityCakeMgr
local ActivityCakeMgr = Class('ActivityCakeMgr',Singleton)
local ActivityCakeDojo = import("Game.Dojo.ActivityCakeDojo")
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

function ActivityCakeMgr:__init()
    self:CleanCache()
end

function ActivityCakeMgr:CleanCache()
    self.activityCakeDojo = nil
    self:CloseTimer()
end

function ActivityCakeMgr:__delete()
    self:CleanCache()
end

function ActivityCakeMgr:InitialDojo(data)
    if isNull(self.activityCakeDojo) then
        self.activityCakeDojo = ActivityCakeDojo.New()
    end
    self.activityCakeDojo:Fill(data)
    self:StartTimer()
end

function ActivityCakeMgr:GetActivityDojo()
    return self.activityCakeDojo
end

function ActivityCakeMgr:GetChapterDataById(questId)
    if isNull(questId) then return end

    if isNull(self.chapterLevelVos) then
        self:InitChapterVos()
    end
    if not isNull(self.chapterLevelVos[questId]) then
        return self.chapterLevelVos[questId]
    end

    printError("can not find chapterLevelVos .... questId is %s",questId)
    return nil
end

function ActivityCakeMgr:UpdateBattleInfo(data)
    local isPass = self:IsPassChapter(data.questId)
    if isPass then
        return
    end
    self:UpdateChapterInfo(data)

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6240, "ActivityCakeMainLineLevelVo", data.questId)
    if not isNull(vo) then
        local nodeId = vo.placeId
        local isPassChapter = self:IsPassChapterNode(nodeId)
        if isPassChapter then
            CS.Engine.UI.UIModule.RemoveDialogRecord(Constants.UITypeIds.ActivityCakeShopMainLineDetailsDialog)
            CS.Engine.UI.UIModule.RemoveDialogRecord(Constants.UITypeIds.ActivityMountainMainLineDetailsDialog)
        end
    end
end

function ActivityCakeMgr:UpdateBossBattleInfo(data)
    self.activityCakeDojo.hp.hp = data.activityHp
    self:StartTimer()
    if checkNumber(data.newMyRankInfo.hurt) > checkNumber(self.activityBossData.playerRank.hurt) then
        self.activityBossData.playerRank.hurt = checkNumber(data.newMyRankInfo.hurt)
    end
end

function ActivityCakeMgr:InitChapterVos()
    self.chapterLevelVos = {}
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6240, "ActivityCakeMainLineLevelVo", true)
    for i, v in ipairs(allVos) do
        if not self.chapterLevelVos[v.placeId] then
            self.chapterLevelVos[v.placeId] = {}
        end
        table.insert(self.chapterLevelVos[v.placeId],v)
    end
end

function ActivityCakeMgr:IsPassChapterNode(nodeId)
    local nodeData = self:GetChapterDataById(nodeId)
    local node = nodeData[#nodeData]
    local isPass = self:IsPassChapter(checkNumber(node.id))
    return isPass
end

function ActivityCakeMgr:IsUnLockFirstChapter(questId)
    local data = self:GetChapterDataById(questId)
    local firstData = data[1]
    local isPass = self:IsPassChapter(checkNumber(firstData.unlockLevel))
    return isPass
end

function ActivityCakeMgr:IsPassChapter(chapterId)
    return self.activityCakeDojo:GetMainChapterId() >= checkNumber(chapterId)
end

function ActivityCakeMgr:SaveActivityData(data)
    self.activityData = data
end

function ActivityCakeMgr:GetActivityData()
    return self.activityData
end

function ActivityCakeMgr:SaveActivityBossData(data)
    self.activityBossData = data
end

function ActivityCakeMgr:GetActivityBossData()
    return self.activityBossData
end

function ActivityCakeMgr:GetActivityHpNum()
    return self.activityCakeDojo:GetHp()
end

function ActivityCakeMgr:UpdateChapterInfo(data)
    self.activityCakeDojo:UpdateInfo(data)
end

function ActivityCakeMgr:UpdateReceiveRewardId(rewardId)
    -- rewardId为0表示一键领取
    if checkNumber(rewardId) == 0 then
        -- 1. 获取所有奖励
        local allRewards = self:GetBossHurtRewards()
        -- 2. 获取所有可领取但未领取的奖励
        local allCanDrawButNotInListRewards = {}
        local historyMaxHurt = self:GetBossHurt()
        for i, reward in ipairs(allRewards) do
            ---@type MidFestivalBossDamageRewardVo
            local rewardVo = reward
            if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
                table.insert(allCanDrawButNotInListRewards, rewardVo)
            end
        end
        -- 3. 将他们全部设置为已领取
        for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
            table.insert(self.activityBossData.receivedDamageRewardIds,rewardVo.id)
        end
        return
    end
    
    if not self:IsHaveDrawBossHurtReward(rewardId) then
        table.insert(self.activityBossData.receivedDamageRewardIds,rewardId)
    end
end

function ActivityCakeMgr:GetBossHurt()
    return checkNumber(self.activityBossData.playerRank.hurt)
end

function ActivityCakeMgr:UpdateBossHurtRedPoint(isCan)
    self.activityCakeDojo:UpdateRedPoint(isCan)
end

function ActivityCakeMgr:IsHaveDrawBossHurtReward(id)
    for i, v in pairs(self.activityBossData.receivedDamageRewardIds) do
        if checkNumber(v) == id then
            return true
        end
    end
    return false
end

function ActivityCakeMgr:IsUnLockShop(id)
    return self.activityCakeDojo:IsUnLockShop(id)
end

function ActivityCakeMgr:RequestShow(callBack)
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseBoss, { activityUuid = self.activityData.id }, function(request, response)
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            if isNull(responseData.upGroup) then
                responseData.upGroup = {}
            end
            self:SaveActivityBossData(responseData)
            if callBack then
                callBack(responseData)
            end
        end
    end)
end

