function ActivityCakeMgr:RequestSplitRankList(scheduleId,callBack)
    GameUtils.Request( Interfaces.OverseaActivityCatParadiseSplitRank, {
        activityUuid = self.activityData.id,
        scheduleId = scheduleId,
    }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
