function ActivityCakeMgr:IsCanOneKeyDrawReward()
    -- 获取所有奖励
    local allRewards = self:GetBossHurtRewards()
    -- 获取所有可领取的奖励
    local historyMaxHurt = self:GetBossHurt()
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end

function ActivityCakeMgr:DrawHurtReward(id,callBack)
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseReceiveBossDamageReward, {activityUuid = self.activityData.id,rewardId = id} , function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        self:UpdateReceiveRewardId(id)
        
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        local isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
        self:UpdateBossHurtRedPoint(isCanOneKeyDraw)
        if callBack then
            callBack()
        end
    end)
end

