function ActivityCakeMgr:GetActivityGoodsNum()
    return checkNumber(self.activityCakeDojo.hp.hp)
end

function ActivityCakeMgr:UpdateActivityHpNum(num)
    self.activityCakeDojo.hp.hp = self.activityCakeDojo.hp.hp + num
    self:StartTimer()
end

function ActivityCakeMgr:GetHpLimit()
    local num = checkNumber(self:GetParametersVo(3).num)
    return num
end

function ActivityCakeMgr:ShowBuyActivityHp()
    local buyTimes  = self.activityCakeDojo.hp.buyTimes
    local buyLimit  = checkNumber(self:GetParametersVo(7).num)
    local buyTips   = localize('今日剩余兑换次数: _num_', {_num_ = buyLimit - buyTimes})
    local priceData = {
        currency = checkNumber(self:GetParametersVo(4).num),
        current  = self:GetBuyHpPrice()
    }
    CfUtils.DialogOpen(Constants.UITypeIds.UICommonBuyItemDialog, {
        goodsId      = self:GetActivityHpId(),
        goodsNum     = checkNumber(self:GetParametersVo(6).num),
        maxHaveNum   = checkNumber(self:GetParametersVo(3).num),
        prices       = { priceData },
        maxBuyNum    = buyTimes >= buyLimit and 0 or 1,
        activityTips = buyTips,
        isShowNum    = true,
        buyCb        = function(price, buyNum)
            local requestData = {activityUuid = self.activityData.id}
            GameUtils.Request(Interfaces.OverseaActivityCatParadiseBuyHp, requestData, function(request, response)
                local responseData = checkTable(response.data)
                -- update hpData
                self.activityCakeDojo.hp = responseData.hp
                
                -- consume goods
                local consumeList = checkTable(responseData.consume)
                GoodsUtils.ConsumeGoods(consumeList, true)
                
                -- draw rewards
                local rewardList = checkTable(responseData.rewards)
                if table.count(rewardList) > 0  then
                    CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = rewardList})
                end
            end)
        end
    })
end

function ActivityCakeMgr:GetBuyHpPrice()
    local buyTimes  = self.activityCakeDojo.hp.buyTimes + 1
    local numData = self:GetParametersVo(5).num
    local priceData = string.split(numData,';')
    if priceData[buyTimes] then
        return checkNumber(priceData[buyTimes])
    end
    return checkNumber(priceData[#priceData])
end

function ActivityCakeMgr:GetNextRecoveryTime()
    return self.activityCakeDojo.hp.lastCdTime
end

function ActivityCakeMgr:GetGoodRecoverSeconds()
    local num = checkNumber(self:GetParametersVo(1).num)
    return num
end

function ActivityCakeMgr:IsHPFull()
    local curCount = self:GetActivityGoodsNum()
    return curCount >= self:GetHpLimit()
end

---开启定时器
function ActivityCakeMgr:StartTimer()
    self:CloseTimer()
    self.timer = CDTimerModule.GetInstance():AddCD(1, function(count, id, delta)
        if count > 0 then
            -- 体力已经恢复满，停止倒计时
            if self:IsHPFull() then
                self.activityCakeDojo.hp.lastCdTime = 0
                self:CloseTimer()
                return
            end
            self:SubCDTime(delta)
        end
    end, CountDownTime, false, true)
end

---移除定时器
function ActivityCakeMgr:CloseTimer()
    if isNotNull(self.timer) then
        CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

---定时器处理
function ActivityCakeMgr:SubCDTime(delta)
    self.activityCakeDojo.hp.lastCdTime = checkNumber(self.activityCakeDojo.hp.lastCdTime) - checkNumber(delta)
    local recoveryHpPerTime = checkNumber(self:GetParametersVo(2).num)
    if self.activityCakeDojo.hp.lastCdTime <= 0 then
        -- 开始恢复体力
        local recoverCount = recoveryHpPerTime
        GoodsUtils.DrawRewards({
            {
                goodsId = self:GetActivityHpId(),
                num = recoverCount
            }
        }, true)
        
        -- 重置倒计时
        self.activityCakeDojo.hp.lastCdTime = checkNumber(self:GetParametersVo(1).num)
        self.activityCakeDojo.hp.hp = self.activityCakeDojo.hp.hp + recoverCount
        self:StartTimer()
    end
end
